import { api, node } from './api.js';
import { activeTab } from './layout.js';
import { $,resources,bindAnalysis,bindSelection,bindErrors,renderNerMetrics,fail } from './course-ui.js';
async function init(){const ctx=await resources('ner');const start=bindAnalysis(ctx,{tasks:['ner']});const errors=bindErrors(ctx,{ner:true});
  async function extras(){if(!ctx.nerId())return;const version=ctx.version,run=encodeURIComponent(ctx.nerId());const [metrics,samples]=await Promise.all([api(`/api/v1/experiments/1/metrics?run_id=${run}`),api(`/api/v1/experiments/1/errors?run_id=${run}&page=1&page_size=2`)]);if(version!==ctx.version)return;
    $('ner-run-note').textContent=`${metrics.run?.dataset||'MSRA NER test personal subset'} · 当前 Run ${ctx.nerId()}。交互结果不写入正式 Gold。`;
    const cards=$('ner-metric-cards');cards.replaceChildren();for(const label of ['PER','LOC','ORG','Overall']){const value=metrics.metrics.ner[label],card=node('article','','metric-card'),head=node('div','','metric-card-head'),line=node('div','','metric-card-values'),rail=node('div','','metric-rail');head.append(node('span',label==='Overall'?'Σ':label[0],'metric-card-icon'),node('h3',label));line.append(node('span',`P ${(value.precision*100).toFixed(2)}%`),node('span',`R ${(value.recall*100).toFixed(2)}%`));rail.style.setProperty('--metric-value',`${value.f1*100}%`);card.append(head,node('strong',`${(value.f1*100).toFixed(2)}%`),node('small','F1 · exact span'),line,rail);cards.append(card);}
    const preview=$('ner-error-preview');preview.replaceChildren();function entityText(entity,text){const start=Array.isArray(entity)?entity[0]:entity.start,end=Array.isArray(entity)?entity[1]:entity.end,type=Array.isArray(entity)?entity[2]:entity.type;return `${Array.from(text).slice(start,end).join('')} · ${type} [${start},${end})`;}
    for(const item of samples.items){const card=node('article','','ner-preview-card'),head=node('div','','ner-preview-head'),text=Array.from(item.text),missed=item.false_negative||[],extra=item.false_positive||[];head.append(node('strong',item.sample_id),node('span',`${missed.length} 处 Gold 差异 · ${extra.length} 处预测差异`,'status-chip status-data'));card.append(head,node('p',`${text.slice(0,100).join('')}${text.length>100?'…':''}`));for(const [label,items,kind] of [['Gold 中的差异',missed,'missed'],['预测中的差异',extra,'extra']]){if(!items.length)continue;const row=node('div','','preview-entity-row');row.append(node('small',label));for(const entity of items.slice(0,3))row.append(node('span',entityText(entity,item.text),`preview-entity ${kind}`));card.append(row);}preview.append(card);}if(!samples.items.length)preview.append(node('p','当前 Run 没有已保存错误案例。'));
  }
  async function refresh(){if(activeTab()==='errors')await errors();if(activeTab()==='ner')await extras();if(activeTab()==='evaluation'){if(!ctx.nerId())throw new Error('unavailable：没有 NER 正式 Run');const version=ctx.version;const value=await api(`/api/v1/experiments/1/metrics?run_id=${encodeURIComponent(ctx.nerId())}`);if(version===ctx.version)renderNerMetrics($('ner-metrics'),value.metrics.ner);}}
  bindSelection(ctx,refresh);document.addEventListener('module-tab',()=>{refresh().catch(fail);if(activeTab()==='ner'&&$('original-text').classList.contains('result-empty'))start();});await refresh();if(activeTab()==='ner')start();
}init().catch(fail);
